import { currentBillTo } from '../../../src/core/billing.mjs';
import { providersState, testProviderConnection } from '../../../src/core/bridge/provider-ops.mjs';
import { freeDailyStatus } from '../../../src/core/openrouter-free.mjs';
import { testSpeech } from '../../../src/core/speech.mjs';

export function register(app) {

// The signed-in person's model credentials, as the credential broker sees them
// (docs/credential-broker.md). Status only: which slots have a key, never a key.
// { enabled:false } with the broker off.
// OpenRouter's daily allowance of `:free` requests (src/core/openrouter-free.mjs), for the
// signed-in person with the credential broker, else for the install's key. The account menu's
// free-request row, the new-run warning and the Providers page read it; ?refresh=1 asks OpenRouter now.
app.get('/api/openrouter/free-daily', async (req, res) => {
  try {
    res.json(await freeDailyStatus({ person: currentBillTo(), force: req.query.refresh === '1' }));
  } catch (err) {
    res.status(500).json({ enabled: false, error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/providers/speech/test', async (req, res) => {
  const b = req.body || {};
  res.json(await testSpeech(typeof b.kind === 'string' ? b.kind : '', b));
});

app.get('/api/providers', async (req, res) => {
  try {
    res.json(await providersState({ quota: req.query.quota === '1' }));
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/providers/:name/test', async (req, res) => {
  // The card tests what is ON SCREEN (§8.1): an unsaved base URL or key is sent with the request,
  // so "Test connection" answers for the endpoint the user is looking at, not the stored one.
  const b = req.body || {};
  res.json(await testProviderConnection(req.params.name, {
    baseUrl: typeof b.baseUrl === 'string' ? b.baseUrl : '',
    ...(typeof b.apiKey === 'string' ? { apiKey: b.apiKey } : {}),
  }));
});
}
